{
  "title": "Discussion on Tax Filing Assistance and Mini‑App Viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing assistance and related costs",
      "claims": [
        {
          "text": "Paying 500 UAH to an acquaintance (Sveta) helped avoid larger penalties after a tax inspector initially approved incorrect declarations.",
          "evidence": [1]
        },
        {
          "text": "The tax filing process can be done in about an hour using Excel, with quarterly reports required.",
          "evidence": [5, 7]
        },
        {
          "text": "Mistakes often stem from mismatched columns and incorrect subtraction rather than the tax calculation itself.",
          "evidence": [8]
        },
        {
          "text": "The calculator the author uses works only with a hryvnia‑based FOP; for foreign‑currency FOPs they had to convert each transaction using the day's exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "mini-app-viability",
      "title": "Viability of a low‑cost cross‑platform mini‑app",
      "claims": [
        {
          "text": "Web platforms are less profitable than Android/iOS because of poor SEO, no organic traffic, and strict paywalls that deter users.",
          "evidence": [11]
        },
        {
          "text": "A fast delivery cycle (under a week) and a cross‑platform stack like Flutter are considered essential for success.",
          "evidence": [12]
        },
        {
          "text": "There is doubt about any market for a 299 UAH app, especially since the password is stored plainly in local storage as a 100 % discount code.",
          "evidence": [20, 23]
        },
        {
          "text": "The app claims to fetch USD/UAH rates every 5 minutes and perform calculations instantly in the browser, but the paid bundle actually contains only the password.",
          "evidence": [29]
        },
        {
          "text": "The project is described as a “free vibe‑code” experiment with no serious intent, inviting others to check the password or buy the app.",
          "evidence": [30, 31, 32]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a sufficient user base (at least ten people) willing to pay 299 UAH for the described mini‑app?",
      "evidence": [20]
    }
  ]
}
